-- Infrastructure schema only. Product reads and writes belong to generated components.
PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
PRAGMA synchronous=FULL;
CREATE TABLE IF NOT EXISTS plan_revisions(namespace TEXT NOT NULL,id TEXT NOT NULL,parent_id TEXT,objective_id TEXT NOT NULL,content_hash TEXT NOT NULL,content_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(namespace,id));
CREATE TABLE IF NOT EXISTS runs(namespace TEXT NOT NULL,id TEXT NOT NULL,plan_id TEXT NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,endly_session_id TEXT,endly_operation_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(namespace,id),FOREIGN KEY(namespace,plan_id) REFERENCES plan_revisions(namespace,id));
CREATE TABLE IF NOT EXISTS attempts(namespace TEXT NOT NULL,id TEXT NOT NULL,run_id TEXT NOT NULL,step_id TEXT NOT NULL,plan_id TEXT NOT NULL,lease_epoch INTEGER NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(namespace,id),FOREIGN KEY(namespace,run_id) REFERENCES runs(namespace,id));
CREATE TABLE IF NOT EXISTS effects(namespace TEXT NOT NULL,id TEXT NOT NULL,attempt_id TEXT NOT NULL,run_id TEXT NOT NULL,business_key TEXT NOT NULL,state TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,evidence_json TEXT,PRIMARY KEY(namespace,id),UNIQUE(namespace,attempt_id),FOREIGN KEY(namespace,attempt_id) REFERENCES attempts(namespace,id));
CREATE TABLE IF NOT EXISTS milestones(namespace TEXT NOT NULL,id TEXT NOT NULL,run_id TEXT NOT NULL,attempt_id TEXT NOT NULL,state TEXT NOT NULL,evidence_json TEXT,PRIMARY KEY(namespace,id),FOREIGN KEY(namespace,run_id) REFERENCES runs(namespace,id));
CREATE TABLE IF NOT EXISTS events(namespace TEXT NOT NULL,id TEXT NOT NULL,run_id TEXT NOT NULL,attempt_id TEXT,sequence INTEGER NOT NULL,kind TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(namespace,id),UNIQUE(namespace,run_id,sequence),FOREIGN KEY(namespace,run_id) REFERENCES runs(namespace,id));
CREATE TABLE IF NOT EXISTS artifacts(namespace TEXT NOT NULL,id TEXT NOT NULL,content_hash TEXT NOT NULL,size_bytes INTEGER NOT NULL,media_type TEXT NOT NULL,key_reference TEXT,publication_state TEXT NOT NULL,PRIMARY KEY(namespace,id));
CREATE TABLE IF NOT EXISTS checkpoints(namespace TEXT NOT NULL,id TEXT NOT NULL,run_id TEXT NOT NULL,plan_id TEXT NOT NULL,run_revision INTEGER NOT NULL,event_sequence INTEGER NOT NULL,manifest_hash TEXT NOT NULL,manifest_json TEXT NOT NULL,publication_state TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(namespace,id),FOREIGN KEY(namespace,run_id) REFERENCES runs(namespace,id));
CREATE TABLE IF NOT EXISTS recorded_events(namespace TEXT NOT NULL,id TEXT NOT NULL,recording_id TEXT NOT NULL,sequence INTEGER NOT NULL,kind TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(namespace,id),UNIQUE(namespace,recording_id,sequence));
